import 'fake-indexeddb/auto';
import { readFileSync } from 'node:fs';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { OntarioTeacherDB } from '../db/database';
import { seedDatabase } from '../db/seeds';
import { PortabilityService } from '../services/portabilityService';
import { clearActiveTeacherId, getIdentityEpoch, selectActingTeacher } from '../services/identityService';
import { MarkingService } from './markingService';

// Generated by the actual seed, marking service and backup exporter at
// b9a8790f4841fa9fd5057e7cfef097f619cbac4a, using its markingBackup.test.ts
// fictional fixture plus a saved pending revision and its own backup roundtrip
// (matching the Windows bootstrap setup, which restores before final export).
// That historical restore backfills participationEventTypes.label from name.
// This is a historical-source
// fixture, not a downloaded Windows CI artifact or a current backup with fields removed.
const legacyJSON = readFileSync(new URL('./fixtures/legacy-b9a8790-backup.json', import.meta.url), 'utf8');
const legacy = JSON.parse(legacyJSON);
const sorted = (rows: any[]) => [...rows].sort((a, b) => a.id.localeCompare(b.id));
const expectedTables = Object.fromEntries(Object.entries({ ...legacy.tables, captureAttachments: [], captureImportReceipts: [] }).map(([name, rows]) => [name, sorted(rows as any[])]));

describe('actual pre-Archive schema4 backup compatibility', () => {
  let db: OntarioTeacherDB;
  let portability: PortabilityService;
  beforeEach(async () => {
    db = new OntarioTeacherDB(`historical-backup-${crypto.randomUUID()}`);
    await seedDatabase(db);
    portability = new PortabilityService(db);
  });
  afterEach(async () => { clearActiveTeacherId(); await db.delete(); });
  async function snapshot() {
    return Object.fromEntries(await Promise.all(db.tables.map(async table => [table.name, sorted(await table.toArray())])));
  }
  it('restores every historical table and byte-bearing record exactly, with an empty default-off Archive', async () => {
    expect(legacy.schemaVersion).toBe(4);
    expect(Object.keys(legacy.tables)).toHaveLength(39);
    expect(legacy.tables.markingAttempts[0]).not.toHaveProperty('archivedAt');
    expect(legacy.tables.markingAttempts[0]).not.toHaveProperty('keepStudentWork');
    const before = await snapshot();
    expect(portability.validateBackupJSON(legacyJSON).tableCount).toBe(41);
    expect(await snapshot()).toEqual(before);
    await portability.restoreFromJSON(legacyJSON);
    expect(await snapshot()).toEqual(expectedTables);
    db.close(); await db.open();
    expect(await snapshot()).toEqual(expectedTables);
    const identity = await selectActingTeacher(db, 'user-tyler');
    const context = await new MarkingService(db).getContext('recovery-essay', { userId: identity.userId, deviceId: identity.deviceId, epoch: getIdentityEpoch() });
    expect(context.archivedAttempts).toEqual([]);
    expect(context.attempts).toHaveLength(1);
    expect(context.attempts[0].keepStudentWork ?? false).toBe(false);
    expect(context.attempts[0].documents[0].original).toBeTruthy();
    expect(context.sessions.some(row => row.draft.pending?.text === 'Fictional unfinished historical feedback')).toBe(true);
    expect(context.commits[0].draft.overallFeedback).toBe('Fictional feedback-only result');
  });
  it('preserves first-export legacy data with only the existing participation label backfill', async () => {
    const firstExport = JSON.parse(legacyJSON);
    for (const eventType of firstExport.tables.participationEventTypes) delete eventType.label;
    await portability.restoreFromJSON(JSON.stringify(firstExport));
    expect(await snapshot()).toEqual(expectedTables);
  });
  it('roundtrips the current exporter after historical recovery without adding or dropping data', async () => {
    await portability.restoreFromJSON(legacyJSON);
    const currentJSON = await portability.createFullBackupJSON();
    expect(JSON.parse(currentJSON).schemaVersion).toBe(5);
    await db.markingSessions.clear();
    await portability.restoreFromJSON(currentJSON);
    expect(await snapshot()).toEqual(expectedTables);
  });
  it.each(['original hash', 'missing table', 'broken link', 'invalid archive date', 'invalid retention flag'] as const)('rejects %s before replacing any live records', async corruption => {
    const corrupt = JSON.parse(legacyJSON);
    if (corruption === 'original hash') corrupt.tables.markingAttempts[0].documents[0].original.hash = '0'.repeat(64);
    if (corruption === 'missing table') delete corrupt.tables.markingSessions;
    if (corruption === 'broken link') corrupt.tables.markingCommits[0].studentAssessmentId = 'missing';
    if (corruption === 'invalid archive date') corrupt.tables.markingAttempts[0].archivedAt = 'invalid';
    if (corruption === 'invalid retention flag') corrupt.tables.markingAttempts[0].keepStudentWork = 'false';
    const before = await snapshot();
    await expect(portability.restoreFromJSON(JSON.stringify(corrupt))).rejects.toThrow();
    expect(await snapshot()).toEqual(before);
  });
});
